-- IMPORT_FULL_SCIENTIFIC_COMMITTEE_CHANNELS_WITH_SPECIALTY_ICONS.sql
-- ملف استيراد كامل لروابط وقنوات اللجنة العلمية المركزية
-- مناسب للتصميم الجديد: التخصصات في الأعلى، وعند الضغط على تخصص تظهر قنواته.
-- يحتوي على أيقونة لكل تخصص داخل specialization_icon.

begin;

alter table public.committee_links
add column if not exists college text;

alter table public.committee_links
add column if not exists specialization text;

alter table public.committee_links
add column if not exists specialization_icon text;

alter table public.committee_links
add column if not exists level text;

alter table public.committee_links
add column if not exists governorate text;

alter table public.committee_links
add column if not exists university text;

create index if not exists committee_links_college_idx on public.committee_links(college);
create index if not exists committee_links_specialization_idx on public.committee_links(specialization);
create index if not exists committee_links_specialization_icon_idx on public.committee_links(specialization_icon);
create index if not exists committee_links_level_idx on public.committee_links(level);

do $$
declare
  v_committee_id public.committees.id%type;
begin
  select id
  into v_committee_id
  from public.committees
  where name = 'اللجنة العلمية المركزية'
  limit 1;

  if v_committee_id is null then
        'اللجنة العلمية المركزية',
        'لجنة تنظم القنوات العلمية وتربط الطالب بقنوات كليته وتخصصه ومستواه.',
        'تنظيم القنوات العلمية حسب الكلية والتخصص والمستوى',
        'تسهيل وصول الطلاب إلى قنواتهم العلمية الرسمية',
        'تحديث الروابط ومتابعتها بشكل مستمر',
        'fa-solid fa-flask-vial',
        'روابط القنوات العلمية',
        '#',
        1,
        true
      )
    returning id into v_committee_id;
  else
    update public.committees
    set
      description = 'لجنة تنظم القنوات العلمية وتربط الطالب بقنوات كليته وتخصصه ومستواه.',
      icon = coalesce(nullif(icon, ''), 'fa-solid fa-flask-vial'),
      link_text = 'روابط القنوات العلمية',
      is_active = true
    where id = v_committee_id;
  end if;

  delete from public.committee_links
  where committee_id = v_committee_id;




  -- ترتيب قنوات جميع المستويات داخل قسم الكلية نفسها
  update public.committee_links
  set
    level = 'جميع المستويات',
    specialization = coalesce(nullif(college, ''), specialization, 'عام'),
    specialization_icon = coalesce(nullif(specialization_icon, ''), 'fa-solid fa-building-columns'),
    description = concat_ws(' | ',
      case when college is not null and college <> '' then 'الكلية: ' || college end,
      case when coalesce(nullif(college, ''), specialization, 'عام') is not null then 'التخصص: ' || coalesce(nullif(college, ''), specialization, 'عام') end,
      'المستوى: جميع المستويات'
    )
  where committee_id = v_committee_id
    and (
      specialization ~* 'جميع\s*المستويات|كل\s*المستويات|لكل\s*المستويات'
      or level ~* 'جميع\s*المستويات|كل\s*المستويات|لكل\s*المستويات'
    );

end $$;

select pg_notify('pgrst', 'reload schema');

commit;
